 "t": "الماء الطهور",
 "d": "الماء الذي يرفع الحدث هو الماء الطهور، فمن لم يجد ماء تيمم (المائدة: 6). والماء المطلق (الباقي على خلقته) يرفع الحدث والخبث باتفاق الفقهاء، ويلحق به عند الجمهور ما تغير بطول مكثه أو بما تولد منه كالطحلب. وقسم الفقهاء المياه إلى: مطلق، وطاهر مطهر مكروه، وطاهر غير مطهر، ونجس. وانفرد الحنفية بقسم المشكوك في طهوريته، وانفرد الحنابلة بقسم المحرم. والماء المتغير بطاهر مخالط تغيراً يمنع إطلاق اسم الماء عليه: طاهر مطهر عند الحنفية ما لم يغلب عليه غيره أو يتغير بالطبخ، وطاهر غير مطهر عند المالكية والشافعية وعلى المذهب عند الحنابلة. والمتغير بنجاسة نجس باتفاق الفقهاء قليلاً كان أو كثيراً. وتفصيل كل مذهب في «أقوال المذاهب في هذه المسألة» تحت هذه البطاقة.",
