 "d": "ذهب الجمهور إلى عدم صحة التيمم إلا بعد دخول وقت ما يتيمم له من فرض أو نفل له وقت مخصوص. وذهب الحنفية إلى جوازه قبل الوقت. وتفصيل ذلك في الخلاف.",
