 "d": "اتفق الفقهاء على أنه من الأركان. وحد المسح محل خلاف: إلى المرفقين أو إلى الكوعين. ويجب نزع الخاتم ونحوه من الحائل عن وصول التراب إلى العضو باتفاق الفقهاء، بخلاف الوضوء، لأن التراب كثيف ليس له سريان الماء.",
