 "t": "ضرب اليدين بباطن الكفين وتفريج الأصابع",
 "d": "ذكرت الموسوعة عن الحنفية سنية الضرب بباطن الكفين وإقبال اليدين وإدبارهما ثم نفضهما اتقاء تلويث الوجه، وسنية تفريج الأصابع. وعند الشافعية تفريق الأصابع في الضربة الأولى وتخفيف الغبار.",
