 "d": "يبطل التيمم عند الحنفية والحنابلة. ولا تبطله عند المالكية، ولا عند الشافعية بالنسبة للمسافر في محل لا يغلب فيه وجود الماء. وعند الشافعية تبطل صلاة المقيم وتلزمه الإعادة إن كان في محل يغلب فيه وجود الماء.",
