 "maliki": "إن تذكر في الوقت أعاد صلاته، وخارجه لا يقضي.",
 "shafii": "يقضي في الأظهر. وإن أضل رحله في رحال وطلبه بإمعان فلم يجده فلا إعادة عليه.",
 "hanbali": "يقضي سواء في الوقت أو خارجه. وإن أضل رحله في رحال وطلبه بإمعان فلم يجده فلا إعادة."
