 "title": "المسح على الخفين: شروطه ومدته وكيفيته",
 "definition": "المسح على الخفين: إصابة البلة لخف مخصوص في محل مخصوص وزمن مخصوص (الموسوعة الفقهية الكويتية). والخف ما يلبس في الرجل ساتراً لها.",
 "hukm": "ثبتت مشروعية المسح على الخفين بالسنة النبوية، وقد رواه أكثر من ثمانين من الصحابة منهم العشرة. والأصل فيه الجواز، وهو رخصة. والغسل أفضل عند جمهور الفقهاء، وعند الحنابلة الأفضل المسح أخذاً بالرخصة. وقد يجب المسح في حالات ذكرتها الموسوعة. وهو مسح من الحدث الأصغر فقط عند الجمهور: لا يجوز لمن وجب عليه الغسل بل ينزع الخف ويغتسل. تبدأ المدة عند الحنفية والشافعية والمشهور عند الحنابلة من أول حدث بعد لبس الخف، وفي رواية عن أحمد من أول مسح بعد الحدث.",
 "pt": 1,
