 "d": "قال همام: بال جرير ثم توضأ ومسح على خفيه، فقيل: تفعل هذا؟ فقال: نعم، رأيت رسول الله ﷺ بال ثم توضأ ومسح على خفيه. قال الأعمش: قال إبراهيم: كان يعجبهم هذا الحديث لأن إسلام جرير كان بعد نزول المائدة. هذا نص الحديث كاملاً، وفيه أن المسح بعد نزول المائدة، فهو ليس منسوخاً بها.",
