 "maliki": "لا توقيت عندهم.",
 "shafii": "يجب نزعهما وغسل الرجلين فقط إذا ظل متوضئاً، وهذا أحد القولين عندهم. والقول الآخر: إعادة الوضوء كله.",
 "hanbali": "يجب إعادة الوضوء كله لانتقاضه في القدمين، لأن الحدث كل لا يتبعض."
