 "kh": ["k5"],
 "t": "ما يستجمر به عند الجمهور",
 "d": "يكون الاستجمار بكل جامد إلا ما مُنع منه، وهو قول جمهور العلماء ومنهم أحمد في الرواية المعتمدة. وفي رواية عن أحمد اختارها أبو بكر: لا يجزئ إلا الأحجار، لأن النبي ﷺ أمر بالأحجار. ودليل الجمهور: قوله ﷺ عن الاستطابة: بثلاثة أحجار ليس فيها رجيع (أبو داود عن خزيمة، كما أوردته الموسوعة)، فلو كان الحجر وحده مراداً لما استثنى الرجيع.",
