 "d": "في المسألة قولان من مصدر آخر غير الموسوعة (الإسلام سؤال وجواب): الشافعية والحنابلة يشترطون الإنقاء وإكمال الثلاثة معاً، ويقوم الحجر الكبير ذو الثلاث شعب مقام ثلاثة. والحنفية والمالكية: الواجب الإنقاء دون العدد، والتثليث مستحب عندهم. ومعنى الإنقاء: إزالة عين النجاسة وبلتها بحيث يخرج الحجر بعد المسحة الأخيرة نقياً يابساً.",
 "ref": "https://islamqa.info/ar/answers/312826"
