 "kh": ["k16"],
 "t": "الاستنجاء والوضوء",
 "d": "الاستنجاء من سنن الوضوء قبله عند الحنفية والشافعية والرواية المعتمدة للحنابلة، فلو أخره عنه جاز وفاتت السنية. وصرح المالكية بأنه لا يعد من سنن الوضوء وإن استحبوا تقديمه. وفي الرواية الأخرى عند الحنابلة: الاستنجاء قبل الوضوء شرط في صحة الصلاة، فلو توضأ قبله لم يصح.",
