 "action": "الحنفية: المرئية تطهر بزوال العين، وغير المرئية ثلاثاً مع العصر. المالكية والشافعية: بلا عدد مع زوال الأوصاف. الحنابلة: سبع غسلات منقية.",
 "dhikr": "لا يُذكر هنا ذكر مخصوص لهذه الخطوة.",
 "dhikrNone": true,
 "whisper": "العدد في هذا الدرس بحسب المذهب.",
