 "id": "istihada",
 "title": "الاستحاضة",
 "definition": "الاستحاضة دم يسيل من المرأة غير دم الحيض والنفاس، وتبعاً للموسوعة: عند الحنفية دم عرق انفجر وليس من الرحم، وعند الشافعية دم علة يسيل من عرق من أدنى الرحم يقال له العاذل. وتفترق عن الحيض: الحيض له وقت (تسع سنين فأكثر) وهو دم طبيعي أسود ثخين منتن غالباً، والاستحاضة دم شاذ أحمر رقيق لا رائحة له. هذا الدرس من مدخل (استحاضة) في الموسوعة الفقهية الكويتية .",
 "hukm": "المستحاضة تصلي وتصوم عند الأئمة الأربعة، ولا يمنعها الاستحاضة شيئاً من العبادات في الأصل، لكن لها أحكاماً خاصة. في الوضوء: الحنفية والحنابلة تتوضأ لوقت كل صلاة مفروضة، والشافعية لكل فرض، والمالكية في أحد قولين لكل صلاة، وفي الثاني تجديد الوضوء لوقت كل صلاة مستحب. في التحفظ من الدم: الحنفية يجب رد الدم أو تقليله، والشافعية يجب غسله والحشو والعصب، والحنابلة يجب الاحتياط في طهارتي الحدث والنجس، وعند مالك تشد المحل ولا تترك الصلاة. وفي تمييز الدم عن الحيض للمعتادة التي استمر بها الدم: الحنفية والشافعية ترد إلى عادتها، والمالكية تبقى أيامها وتستظهر بثلاثة أيام، والحنابلة تجلس أيام عادتها. والتفصيل لكل مذهب تحت بطاقات هذا الدرس وفي تبويب الخلاف. وهذا الدرس لا يغني عن سؤال أهل العلم في حالتك.",
