 "maliki": "تبقى أيامها المعتادة وتستظهر بثلاثة أيام، ثم هي مستحاضة تغتسل وتصلي وتصوم وتطوف ويأتيها زوجها، وتغتسل عند تمام الخمسة عشر استحباباً لا إيجاباً (ظاهر رواية ابن القاسم عن مالك).",
 "shafii": "ترد إلى حيضها وطهرها السابقين قدراً ووقتاً، وتثبت العادة بمرة في الأصح.",
 "hanbali": "تجلس أيام عادتها وتغتسل عند انقضائها ثم تتوضأ بعد ذلك لوقت كل صلاة."
