 "hanbali": "إن كان الأسود في زمن العادة عمل بهما. وإن كان أكثر أو أقل ويصلح حيضاً ففيه روايتان: اعتبار العادة (لحديث أم حبيبة: امكثي قدر ما كانت تحبسك حيضتك ثم اغتسلي وصلي كما أوردته الموسوعة)، أو تقديم التمييز."
