 "definition": "العفو عن النجاسة: أن يرخّص الشرع في بقاء قدر أو نوع من النجاسة على الثوب أو البدن أو المكان للمشقة وعموم البلوى، فلا تبطل به الصلاة. وقد اختلفت المذاهب في أنواع ما يعفى عنه وقدره. وعند الحنفية: العفو عن فساد الصلاة، وتبقى كراهة التحريم إن بلغت الدرهم وكراهة التنزيه إن لم تبلغ (كما في الموسوعة). هذا الدرس من مدخل (نجاسة) في الموسوعة الفقهية الكويتية .",
 "hukm": "الأصل وجوب إزالة النجاسة للصلاة، واتفقت المذاهب في الجملة على العفو عن أنواع للمشقة، لكن اختلفت في الضابط: قدر الدرهم عند الحنفية والمالكية، وما لا يدركه البصر المعتدل عند الشافعية، واليسير عرفاً عند الحنابلة. والجدول يعرض كل مذهب وحده.",
